"use client";

import { useEffect, useState, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import { useAuthStore } from "@/stores/auth-store";
import StatusMessage from "@/components/ui/status-message";

// TanStack Router의 beforeLoad + redirect 대신, 토큰은 브라우저(localStorage)에만 있으므로
// 복원이 끝난 뒤 토큰이 없으면 /login으로 보내요.
export default function AuthGuard({ children }: { children: ReactNode }) {
  const router = useRouter();
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    Promise.resolve(useAuthStore.persist.rehydrate()).then(() => {
      if (useAuthStore.getState().accessToken) setIsReady(true);
      else router.replace("/login");
    });
  }, [router]);

  if (!isReady) {
    return (
      <main className="mx-auto w-full max-w-6xl flex-1 px-4 py-12 sm:px-6">
        <StatusMessage>로그인 정보를 확인하는 중이에요.</StatusMessage>
      </main>
    );
  }

  return <>{children}</>;
}
